<header class="page-header"><div><p class="eyebrow">Campaign research</p><h1>Lead Finder</h1><p>Candidate companies found by the campaign operator. Review the evidence before moving anything into active prospecting.</p></div></header><nav class="tab-list" aria-label="Lead status"><?php foreach(['pending'=>'Pending','approved'=>'Approved','rejected'=>'Rejected'] as $key=>$label):?><a href="<?= $escape($indexUrl.'?status='.$key) ?>"<?= $status===$key?' aria-current="page"':'' ?>><?= $escape($label) ?></a><?php endforeach;?></nav><?php if($candidates===[]):?><section class="empty-state"><h2>No <?= $escape($status) ?> leads</h2><p>Run the campaign operator’s <code>find</code> command with <code>--save</code> to populate this queue.</p></section><?php else:?><div class="table-scroll" tabindex="0" role="region" aria-label="Lead candidates"><table><thead><tr><th>Company</th><th>Fit</th><th>Evidence</th><th>Source</th><th>Review</th></tr></thead><tbody><?php foreach($candidates as $candidate):?><tr><th scope="row"><?php if($candidate['website']):?><a href="<?= $escape($candidate['website']) ?>" rel="noopener noreferrer"><?= $escape($candidate['name']) ?></a><?php else:?><?= $escape($candidate['name']) ?><?php endif;?><br><small><?= $escape($candidate['address']??'') ?></small></th><td><strong><?= $escape(str_replace('_',' ',$candidate['fit'])) ?></strong><br><?= $escape($candidate['score']) ?> points</td><td><ul><?php foreach($candidate['evidence'] as $reason):?><li><?= $escape($reason) ?></li><?php endforeach;?></ul></td><td><?= $escape($candidate['source']) ?><br><small><?= $escape($candidate['category']??'') ?></small></td><td><?php if($status==='pending'):?><form method="post" action="<?= $escape($reviewUrl((int)$candidate['id'])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><label>Segment<select name="segment" required><?php foreach($segments as $key=>$label):?><option value="<?= $escape($key) ?>"><?= $escape($label) ?></option><?php endforeach;?></select></label><button name="status" value="approved">Approve &amp; create prospect</button><button class="button--secondary" name="status" value="rejected">Reject</button></form><?php else:?><?= $escape($candidate['reviewed_at']??'') ?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
